 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
 });

 await foreach (var update in agent.RunStreamingAsync(
     $"Research the following topic thoroughly and provide a summary: {topic}",
     session: null,
     runOptions))
 {
     if (!string.IsNullOrEmpty(update.Text))
     {
         Console.Write(update.Text);
     }
 }

 Console.WriteLine("\n\n=== Research Notes Collected ===");
 var notes = host.Services.GetRequiredService<ResearchNotes>();
 if (notes.Notes.Count == 0)
 {
     Console.WriteLine("  (No notes were taken)");
 }
 else
 {
     foreach (var note in notes.Notes)
     {
         Console.WriteLine($"  [{note.Category}] {note.Content}");
     }
 }

 // --- Supporting Types ---

 public sealed class ResearchNotes
 {
     private readonly List<Note> _notes = [];
     public IReadOnlyList<Note> Notes => _notes;

     public void Add(string category, string content)
     {
         _notes.Add(new Note(category, content));
     }

     public record Note(string Category, string Content);
 }

 public sealed class ResearchTools(ResearchNotes notes)
 {
     [Description("Search the web for information on a query. Returns relevant search results.")]
     public string WebSearch([Description("The search query")] string query)
     {
         // Simulated web search results for demonstration.
         // In production, replace with a real search API (e.g., Bing Search API).
         Console.WriteLine($"  [Tool] Searching web: \"{query}\"");
         return $$"""
             Search results for "{{query}}":
             1. {{query}} - Overview and key concepts from Wikipedia
                Summary: Provides foundational information about {{query}} including history,
                current state, and major developments.
             2. Latest developments in {{query}} - TechNews
                Summary: Recent advances and breakthroughs related to {{query}}
                from the past year.
             3. {{query}}: Expert Analysis - Research Journal
                Summary: In-depth expert analysis covering implications, challenges,
                and future directions of {{query}}.
             """;
     }

     [Description("Take a research note to remember a key finding.")]
     public string TakeNote(
         [Description("Category of the note (e.g., 'definition', 'history', 'current_state', 'future')")] string category,
         [Description("The content of the note")] string content)
     {
         notes.Add(category, content);
         Console.WriteLine($"  [Tool] Note taken: [{category}]");
         return $"Note saved under '{category}'.";
     }

     [Description("Get all research notes taken so far.")]
     public string GetNotes()
     {
         if (notes.Notes.Count == 0)
             return "No notes taken yet.";

         return string.Join("\n", notes.Notes.Select(n => $"[{n.Category}] {n.Content}"));
     }
 }
